<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { Search, Heart, Plus, Minus, MapPin, Clock3, ShoppingBag, ArrowRight, X, Leaf, CalendarDays, Check, LoaderCircle, Trash2 } from '@lucide/vue'
import { state, api, attempt, notify, requireStudent, refreshStudent, refreshMenu, cartCount, cartTotal, money, sameId, dateString, createRequestId } from '../state'
const router=useRouter(),route=useRoute()
const windowId=ref('1'),query=ref(''),category=ref('all'),favoritesOnly=ref(route.query.favorites==='1')
const date=ref(dateString()),slots=ref([]),slotId=ref(''),remark=ref(''),cutlery=ref(true)
const sheet=ref(false),submitting=ref(false),changing=ref(false),requestId=ref(createRequestId())
const currentWindow=computed(()=>state.windows.find(w=>sameId(w.id,windowId.value)))
const cartWindow=computed(()=>{const dish=state.menu.find(d=>sameId(d.id,state.cart[0]?.dishId));return state.windows.find(w=>sameId(w.id,dish?.windowId))||currentWindow.value})
const cartWindowId=computed(()=>cartWindow.value?.id||windowId.value)
const filtered=computed(()=>state.menu.filter(d=>sameId(d.windowId,windowId.value)&&Number(d.status)===1&&(category.value==='all'||sameId(d.categoryId,category.value))&&(!favoritesOnly.value||favorite(d.id))&&`${d.name}${d.tags}${d.description}`.includes(query.value.trim())))
const chosenSlot=computed(()=>slots.value.find(s=>sameId(s.id,slotId.value)))
function favorite(id){return state.favorites.some(value=>sameId(value,id))}
function count(id){return state.cart.find(row=>sameId(row.dishId,id))?.number||0}
async function change(dish,delta){if(!requireStudent()||changing.value)return;changing.value=true;await attempt(async()=>{await api('/student/cart',{method:'POST',body:{dishId:dish.id,delta}});requestId.value=createRequestId();await refreshStudent()});changing.value=false}
async function toggleFavorite(dish){if(!requireStudent())return;await attempt(async()=>{await api(`/student/favorites/${dish.id}?enabled=${!favorite(dish.id)}`,{method:'PUT'});await refreshStudent()})}
async function clear(){await attempt(async()=>{await api('/student/cart',{method:'DELETE'});await refreshStudent();requestId.value=createRequestId()})}
let sequence=0
async function loadSlots(){const current=++sequence;await attempt(async()=>{const available=await api(`/public/slots?windowId=${cartWindowId.value}&date=${date.value}`);if(current!==sequence)return;if(!available.length&&date.value===dateString()){date.value=dateString(1);return}slots.value=available;if(!available.some(s=>sameId(s.id,slotId.value)&&Number(s.reserved)<Number(s.capacity)))slotId.value=available.find(s=>Number(s.reserved)<Number(s.capacity))?.id||''})}
function openCart(){if(!requireStudent())return;if(!cartCount.value)return notify('先选一道喜欢的菜吧');sheet.value=true}
async function submit(){if(submitting.value||!chosenSlot.value)return;submitting.value=true;await attempt(async()=>{await api('/student/orders',{method:'POST',body:{slotId:slotId.value,requestId:requestId.value,remark:remark.value,needCutlery:cutlery.value}});sheet.value=false;requestId.value=createRequestId();remark.value='';await Promise.all([refreshStudent(),refreshMenu()]);notify('预约已创建，请在 15 分钟内完成演示支付');router.push('/m/orders')});submitting.value=false}
watch([cartWindowId,date],loadSlots)
onMounted(loadSlots)
</script>
<template>
  <div class="phone-ordering">
    <section class="phone-hero"><div><p>HELLO, GOOD MEAL</p><h1>下课了，<br>好好吃顿饭。</h1><span><Clock3 :size="11" />提前预约 · 到窗取餐</span></div><img src="/images/hero.jpg" alt="校园轻食演示图片" /><small>演示环境 · 支付不扣款</small></section>
    <div class="phone-meal-heading"><h2>今天去哪吃？</h2><span>校园好味，等你来选</span></div>
    <div class="phone-windows"><button v-for="window in state.windows" :key="window.id" :class="{active:sameId(windowId,window.id)}" @click="windowId=String(window.id);category='all';query='' "><small>{{ window.canteenName }}</small><b>{{ window.name }}</b><span>{{ window.location.split('·')[1] }}<Check v-if="sameId(windowId,window.id)" :size="11" /></span></button></div>
    <div class="phone-window-info"><MapPin :size="13" /><span>{{ currentWindow?.location }}</span><label>开放预约</label></div>
    <div class="phone-menu-search"><Search :size="17" /><input v-model="query" aria-label="搜索菜品" placeholder="搜一搜，今天想吃什么" /><button :class="{selected:favoritesOnly}" aria-label="只看收藏" @click="requireStudent()&&(favoritesOnly=!favoritesOnly)"><Heart :size="17" :fill="favoritesOnly?'currentColor':'none'" /></button></div>
    <section class="phone-menu"><nav class="phone-categories"><button v-for="item in [{id:'all',name:'全部'},{id:1,name:'主食'},{id:2,name:'轻食'},{id:3,name:'面点'},{id:4,name:'汤饮'}]" :key="item.id" :class="{active:sameId(category,item.id)}" @click="category=item.id">{{ item.name }}</button><span><Leaf :size="17" />按需<br>点餐</span></nav><div class="phone-dishes"><div class="phone-dishes-heading">{{ favoritesOnly?'我的收藏':currentWindow?.name }}<small>{{ filtered.length }} 道好味</small></div><p v-if="!filtered.length" class="phone-no-dishes">这里还没有菜品，换个分类或窗口看看吧。</p><article v-for="dish in filtered" :key="dish.id" class="phone-dish"><div class="phone-dish-image"><img :src="dish.image" :alt="`${dish.name}演示示意图`" loading="lazy" /><span v-if="!Number(dish.stock)">售罄</span></div><div class="phone-dish-copy"><div><h3>{{ dish.name }}</h3><button :class="{selected:favorite(dish.id)}" :aria-label="`${favorite(dish.id)?'取消收藏':'收藏'}${dish.name}`" @click="toggleFavorite(dish)"><Heart :size="14" :fill="favorite(dish.id)?'currentColor':'none'" /></button></div><p>{{ dish.tags?.split(',').join(' · ') }}</p><small>余 {{ dish.stock }} 份<span>约 {{ dish.calories }} kcal</span></small><div class="phone-dish-bottom"><strong><small>¥</small>{{ money(dish.price) }}</strong><div v-if="count(dish.id)" class="phone-quantity"><button :disabled="changing" :aria-label="`减少${dish.name}`" @click="change(dish,-1)"><Minus :size="12" /></button><span>{{ count(dish.id) }}</span><button :disabled="changing||Number(count(dish.id))>=Number(dish.stock)" :aria-label="`添加${dish.name}`" @click="change(dish,1)"><Plus :size="14" /></button></div><button v-else class="phone-add" :disabled="changing||!Number(dish.stock)" :aria-label="`添加${dish.name}`" @click="change(dish,1)"><Plus :size="17" /></button></div></div></article><p class="phone-food-note">图片及营养数值为演示示意<br>珍惜食物，好好吃饭。</p></div></section>
    <div class="phone-cart-bar"><button class="phone-cart-summary" @click="openCart"><span><ShoppingBag :size="23" /><b v-if="cartCount">{{ cartCount }}</b></span><div><strong v-if="cartCount">¥{{ money(cartTotal) }}</strong><strong v-else>餐盘还是空的</strong><small>{{ cartCount?`已选 ${cartCount} 份，到窗取餐`:'选一点喜欢的，给下一餐' }}</small></div></button><button class="button button-primary" :disabled="!cartCount" @click="openCart">去预约<ArrowRight :size="15" /></button></div>
    <div v-if="sheet" class="phone-sheet-backdrop" @click.self="!submitting&&(sheet=false)"><section class="phone-cart-sheet" role="dialog" aria-modal="true" aria-labelledby="phone-checkout"><div class="phone-sheet-top"><h2 id="phone-checkout">安排好，下一餐。</h2><button class="icon-button" aria-label="关闭餐盘" @click="sheet=false"><X :size="19" /></button></div><div class="phone-sheet-location"><MapPin :size="16" /><div><b>{{ cartWindow?.name }}</b><p>{{ cartWindow?.location }}</p></div><button class="icon-button" aria-label="清空餐盘" @click="clear"><Trash2 :size="15" /></button></div><div class="phone-sheet-items"><div v-for="item in state.cart" :key="item.id"><img :src="item.image" :alt="item.name" /><span><b>{{ item.name }}</b><small>¥{{ money(item.amount) }}</small></span><div class="phone-quantity"><button :disabled="changing" :aria-label="`餐盘减少${item.name}`" @click="change({id:item.dishId},-1)"><Minus :size="12" /></button><span>{{ item.number }}</span><button :disabled="changing" :aria-label="`餐盘添加${item.name}`" @click="change({id:item.dishId},1)"><Plus :size="12" /></button></div></div></div><div class="phone-sheet-time"><h3><CalendarDays :size="15" />约个取餐时间</h3><div class="date-switch"><button :class="{active:date===dateString()}" @click="date=dateString()">今天</button><button :class="{active:date===dateString(1)}" @click="date=dateString(1)">明天</button></div><select v-model="slotId" aria-label="取餐时段"><option value="" disabled>选择取餐时段</option><option v-for="slot in slots" :key="slot.id" :value="slot.id" :disabled="Number(slot.reserved)>=Number(slot.capacity)">{{ slot.startTime }} – {{ slot.endTime }} · 余 {{ Number(slot.capacity)-Number(slot.reserved) }} 位</option></select></div><label class="phone-remark">给窗口留句话<textarea v-model="remark" maxlength="100" rows="2" placeholder="例如：少辣，不要香菜" /></label><label class="phone-cutlery"><input v-model="cutlery" type="checkbox" />需要一份餐具<span>自带餐盒，少一点浪费</span></label><div class="phone-sheet-total"><span>预计合计<small>共 {{ cartCount }} 份</small></span><strong>¥{{ money(cartTotal) }}</strong></div><p class="phone-sheet-tip">演示支付不扣款，最终金额以生成的预约为准。</p><button class="button button-primary full" :disabled="submitting||!slotId||!cartCount" @click="submit"><LoaderCircle v-if="submitting" class="spin" :size="15" />确认预约<ArrowRight :size="17" /></button></section></div>
  </div>
</template>
